package lib

import "testing"

type observationStep struct {
	forgetId int32 // 0 = no forget() before this step
	id       int32
	current  string
	observed string
	now      int64
	want     bool
}

// TestInstanceStatusObservationsTranscript replays the exact transcript produced by
// server/src/lib/instance-status-observation.ts for the same call sequence (the
// golden trace was generated by importing the TypeScript class with tsx).
func TestInstanceStatusObservationsTranscript(t *testing.T) {
	observations := NewInstanceStatusObservations()
	steps := []observationStep{
		// A first error observation is never applied; it starts the window.
		{id: 1, current: "running", observed: "error", now: 0, want: false},
		{id: 1, current: "running", observed: "error", now: 29_999, want: false},
		// 30 s after the *first* observation it applies, and keeps applying even
		// though the 30 s window has not elapsed since `last`.
		{id: 1, current: "running", observed: "error", now: 30_000, want: true},
		{id: 1, current: "running", observed: "error", now: 30_001, want: true},
		// forget() drops the window, so the next observation starts over.
		{forgetId: 1, id: 1, current: "running", observed: "error", now: 30_002, want: false},
		// error → error applies immediately and clears the window.
		{id: 2, current: "error", observed: "error", now: 100, want: true},
		{id: 2, current: "error", observed: "error", now: 200, want: true},
		// Non-error transitions apply immediately.
		{id: 3, current: "running", observed: "stopped", now: 300, want: true},
		{id: 3, current: "running", observed: "stopped", now: 400, want: true},
		// Unknown statuses on either side are rejected and clear the window.
		{id: 4, current: "deleted", observed: "running", now: 500, want: false},
		{id: 4, current: "running", observed: "deleted", now: 600, want: false},
		{id: 5, current: "creating", observed: "error", now: 700, want: false},
		// Expiry sweep: `last` older than 15 minutes forgets the entry, which then
		// re-enters as a first observation (false). Exactly 15 minutes does not
		// expire it (the comparison is strict), which is why 900_000 already applies.
		{id: 6, current: "running", observed: "error", now: 0, want: false},
		{id: 6, current: "running", observed: "error", now: 900_000, want: true},
		{id: 6, current: "running", observed: "error", now: 900_001, want: true},
		{id: 6, current: "running", observed: "error", now: 930_000, want: true},
		{id: 6, current: "running", observed: "error", now: 930_001, want: true},
	}

	for index, step := range steps {
		if step.forgetId != 0 {
			observations.Forget(step.forgetId)
		}
		got := observations.ShouldApply(step.id, step.current, step.observed, step.now)
		if got != step.want {
			t.Fatalf("step %d shouldApply(%d, %q, %q, %d) = %v, want %v",
				index, step.id, step.current, step.observed, step.now, got, step.want)
		}
	}
	// Two windows survive, matching the TypeScript (verified with tsx:
	// errors.size === 2, keys [1, 6]). Instance 1 was forgotten and then observed
	// again at 30_002, so at 900_000 the expiry sweep still sees it as fresh
	// (900_000 - 30_002 <= 900_000); instance 6 opened its window at 0.
	if got := observations.Len(); got != 2 {
		t.Errorf("after the transcript two windows should be remembered, Len = %d", got)
	}
}

// TestInstanceStatusObservationsExpiry pins the > 15 minute boundary.
func TestInstanceStatusObservationsExpiry(t *testing.T) {
	exact := NewInstanceStatusObservations()
	if exact.ShouldApply(9, "running", "error", 0) {
		t.Fatal("first observation must not apply")
	}
	if !exact.ShouldApply(9, "running", "error", InstanceStatusObservationExpiryMs) {
		t.Error("at exactly 15 minutes the entry is still alive, so the 30 s window has elapsed → true")
	}

	beyond := NewInstanceStatusObservations()
	if beyond.ShouldApply(9, "running", "error", 0) {
		t.Fatal("first observation must not apply")
	}
	if beyond.ShouldApply(9, "running", "error", InstanceStatusObservationExpiryMs+1) {
		t.Error("past 15 minutes the entry expires and the observation is a first observation again → false")
	}
	if got := beyond.Len(); got != 1 {
		t.Errorf("the expired instance is re-recorded, Len = %d, want 1", got)
	}
}

// TestInstanceStatusObservationsMemoryCap pins the 10_000-entry eviction: the
// oldest *inserted* key goes, not the one with the oldest `last` timestamp.
func TestInstanceStatusObservationsMemoryCap(t *testing.T) {
	observations := NewInstanceStatusObservations()
	for id := int32(0); id < InstanceStatusObservationMaxEntries; id++ {
		if observations.ShouldApply(id, "running", "error", int64(id)) {
			t.Fatalf("first observation for %d must not apply", id)
		}
	}
	if got := observations.Len(); got != InstanceStatusObservationMaxEntries {
		t.Fatalf("Len = %d, want %d", got, InstanceStatusObservationMaxEntries)
	}

	// A new instance at the cap evicts key 0 (oldest insertion).
	if observations.ShouldApply(10_000, "running", "error", 20_000) {
		t.Fatal("new instance must start with false")
	}
	// Key 0 was evicted, so re-observing it records a fresh window → false. If a
	// different key had been evicted, key 0 would still hold first=0 and this
	// would be true.
	if observations.ShouldApply(0, "running", "error", 20_001) {
		t.Fatal("key 0 should have been evicted and start a fresh window")
	}
	// And the most recent key keeps its window.
	if observations.ShouldApply(10_000, "running", "error", 20_002) {
		t.Fatal("key 10000's window was just opened, so 2 ms later is still false")
	}
	if got := observations.Len(); got != InstanceStatusObservationMaxEntries {
		t.Errorf("Len = %d, want %d (the cap must hold)", got, InstanceStatusObservationMaxEntries)
	}
}

func TestInstanceStatusObservationsNow(t *testing.T) {
	now := InstanceStatusObservationsNow()
	if now < 1_700_000_000_000 {
		t.Fatalf("InstanceStatusObservationsNow() = %d, which is not a plausible unix-millis value", now)
	}
	if InstanceStatusObservationsShared == nil {
		t.Fatal("InstanceStatusObservationsShared must be initialised")
	}
}
